--- Looks up Russian translation for an item name.
--- If not found, returns the original English name as safe fallback.
---@param enName string|nil
---@return string|nil
function ItemNamesRU:Get(enName)
    if not enName then
        return nil
    end
    return self.map[enName] or enName
end

return ItemNamesRU
